import {state,t,esc,icon,btn,link,navLink,badge,statusBadge,statusText,title,panel,panelBody,fact,table,field,selectField,notice,isAdmin,canSeeAudit} from './ui.js';
import {users} from './data.js';
import {footer,deniedPage} from './pages.js';
export function appearance(){return `<h2>${t('A workspace that feels right','Size uygun bir çalışma alanı')}</h2><p>${t('Choose a theme and information density. Your preference stays on this device.','Tema ve bilgi yoğunluğunu seçin. Tercihiniz bu cihazda saklanır.')}</p><div class="field-label">${t('Color mode','Renk modu')}</div><div class="appearance-options">${[['light',t('Light','Açık')],['dark',t('Dark','Koyu')],['system',t('System','Sistem')]].map(([key,label])=>`<button class="appearance-option ${state.theme===key?'active':''}" data-action="set-theme" data-value="${key}" aria-pressed="${state.theme===key}"><div class="mini-app ${key}"><i></i><span></span></div><span class="theme-choice">${label}${state.theme===key?icon('CircleCheck'):icon('Circle')}</span></button>`).join('')}</div><div class="switch-row mt24"><div><h3>${t('Compact tables','Kompakt tablolar')}</h3><p>${t('Use 48 px rows to see more information at once.','Tek seferde daha fazla bilgi için 48 piksel satırlar kullanın.')}</p></div><input class="switch" type="checkbox" aria-label="${t('Compact tables','Kompakt tablolar')}" data-change="density" ${state.density==='compact'?'checked':''}></div><div class="switch-row"><div><h3>${t('Language','Dil')}</h3><p>${t('Product terminology stays consistent across pages.','Ürün terminolojisi tüm sayfalarda tutarlı kalır.')}</p></div><select class="filter-select" data-change="language" aria-label="${t('Language','Dil')}"><option value="en" ${state.lang==='en'?'selected':''}>English</option><option value="tr" ${state.lang==='tr'?'selected':''}>Türkçe</option></select></div>`}
export function settingsPage(tab='appearance'){if(!isAdmin())return deniedPage();const tabs=[['appearance','Palette',t('Appearance','Görünüm')],['general','Settings2',t('General','Genel')],['mail','Mail',t('Notifications','Bildirimler')],['alerts','Bell',t('Alert thresholds','Uyarı eşikleri')],['sso','ShieldCheck',t('Single sign-on','Tek oturum açma')],['backups','DatabaseBackup',t('Backups','Yedekler')],['https','LockKeyhole',t('HTTPS certificate','HTTPS sertifikası')],['forwarding','Network',t('Audit forwarding','Denetim yönlendirme')]];
 let body='';
 if(tab==='appearance')body=appearance();
 if(tab==='general')body=`<h2>${t('General settings','Genel ayarlar')}</h2><p>${t('Defaults for this Alice installation.','Bu Alice kurulumu için varsayılanlar.')}</p><form data-form="settings">${field(t('Organization name','Kurum adı'),'organization','Atlas Infrastructure')}${selectField(t('Default language','Varsayılan dil'),'default-locale',[['en','English'],['tr','Türkçe']],state.lang)}${selectField(t('Display time zone','Görüntüleme saat dilimi'),'time-zone',[['UTC','UTC'],['Europe/Istanbul','Europe/Istanbul'],['Europe/London','Europe/London']],'UTC',t('Display preference proposed for the new interface; server schedules retain their own time zone.','Yeni arayüz için önerilen görüntüleme tercihi; sunucu zamanlamaları kendi saat dilimini korur.'))}${field(t('Idle timeout (minutes)','Hareketsizlik süresi (dakika)'),'idle-timeout',30,'number','', 'min="5" max="480" required')}<div class="form-actions">${btn(t('Save changes','Değişiklikleri kaydet'),'','Check','primary','type="submit"')}</div></form>`;
 if(tab==='mail')body=`<h2>${t('Notifications','Bildirimler')}</h2><p>${t('Mail delivery and the people who receive operational alerts.','E-posta iletimi ve operasyon uyarılarının alıcıları.')}</p>${notice(t('SMTP configuration · sample','SMTP yapılandırması · örnek'),t('Delivery is simulated in this prototype. No messages are sent.','Bu prototipte iletim simüle edilir. Mesaj gönderilmez.'))}<form data-form="settings" class="mt24"><div class="grid2">${field(t('SMTP host','SMTP sunucusu'),'smtp-host','smtp.atlas.example')}${field(t('Port','Port'),'smtp-port',587,'number')}</div>${field(t('Sender address','Gönderen adresi'),'smtp-from','alice@atlas.example','email')}${field(t('Recipients','Alıcılar'),'recipients','operations@atlas.example')}${selectField(t('Connection security','Bağlantı güvenliği'),'smtp-security',[['starttls','STARTTLS'],['tls','TLS']],'starttls')}<div class="form-actions">${btn(t('Test delivery','İletimi test et'),'test-delivery','Mail')}${btn(t('Save changes','Değişiklikleri kaydet'),'','Check','primary','type="submit"')}</div></form>`;
 if(tab==='alerts')body=`<h2>${t('Alert thresholds','Uyarı eşikleri')}</h2><p>${t('Warn early enough to act. Keep urgent signals distinct.','Harekete geçmek için yeterince erken uyarın. Acil sinyalleri ayırt edin.')}</p><form data-form="settings">${field(t('Days before certificate expiry','Sertifika bitişinden önceki günler'),'thresholds','60, 30, 14, 7, 1','text',t('Comma-separated days. Expired certificates are always a separate state.','Virgülle ayrılmış günler. Süresi dolan sertifikalar her zaman ayrı bir durumdur.'))}${[['failed-deploy',t('Deployment failures','Başarısız dağıtımlar'),t('Include rollback and recovery outcomes.','Geri alma ve kurtarma sonuçlarını içerir.')],['host-change',t('Changed server identities','Değişen sunucu kimlikleri'),t('Alert when the observed host key differs.','Gözlemlenen sunucu anahtarı farklıysa uyar.')],['backup-alert',t('Backup failures','Başarısız yedeklemeler'),t('Make recovery issues visible to administrators.','Kurtarma sorunlarını yöneticilere göster.')]].map(([id,name,desc])=>`<div class="switch-row"><div><h3>${name}</h3><p>${desc}</p></div><input class="switch" name="${id}" type="checkbox" aria-label="${name}" checked></div>`).join('')}<div class="form-actions">${btn(t('Save changes','Değişiklikleri kaydet'),'','Check','primary','type="submit"')}</div></form>`;
 if(tab==='sso')body=`<h2>${t('Single sign-on','Tek oturum açma')}</h2><p>${t('Connect an OpenID Connect provider and map groups to Alice roles.','Bir OpenID Connect sağlayıcısı bağlayın ve grupları Alice rolleriyle eşleştirin.')}</p><div class="usage-node"><span class="resource-icon azure">${icon('Building2')}</span><div class="grow"><strong>Microsoft Entra ID</strong><p>OIDC · atlas.example</p></div>${badge(t('Enabled','Etkin'),'success')}</div><h3 class="mt24 mb16">${t('Group mappings','Grup eşlemeleri')}</h3>${table([t('Identity provider group','Kimlik sağlayıcı grubu'),t('Alice role','Alice rolü')],[['alice-administrators','admin'],['alice-operators','operator'],['alice-auditors','auditor']].map(([g,r])=>`<tr><td class="mono">${g}</td><td>${statusText(r)}</td></tr>`))}<div class="mt24">${notice(t('Keep a local recovery administrator','Yerel kurtarma yöneticisi bulundurun'),t('A local account provides access if the identity provider is unavailable.','Kimlik sağlayıcısına ulaşılamadığında yerel hesap erişim sağlar.'))}</div><div class="form-actions">${btn(t('Review provider','Sağlayıcıyı incele'),'edit-sso','Settings2')}</div>`;
 if(tab==='backups')body=`<h2>${t('Backups & recovery','Yedekleme ve kurtarma')}</h2><p>${t('Encrypted backups protect recovery data. Test your restore procedure separately.','Şifreli yedekler kurtarma verisini korur. Geri yükleme sürecinizi ayrıca test edin.')}</p>${notice(t('Last backup completed','Son yedekleme tamamlandı'),'12 Oct 2026 · 02:00 UTC · '+t('Checksum matches','Sağlama toplamı eşleşiyor'))}<div class="grid2 mt24"><div class="micro-card"><span class="eyebrow">${t('SCHEDULE','ZAMANLAMA')}</span><h2 class="mt16">02:00 UTC</h2><p>${t('Every day','Her gün')}</p></div><div class="micro-card"><span class="eyebrow">${t('RETENTION','SAKLAMA')}</span><h2 class="mt16">14 ${t('days','gün')}</h2><p>${t('Local encrypted backups','Yerel şifreli yedekler')}</p></div></div><div class="mt24">${table([t('Backup','Yedek'),t('Size','Boyut'),t('Check','Kontrol'),''],[12,11,10].map(d=>`<tr><td class="mono">alice-2026-10-${d}.enc<p>02:00 UTC</p></td><td>48.${d-7} MB</td><td>${badge(t('Checksum OK','Sağlama geçerli'),'success')}</td><td>${btn(t('Details','Ayrıntılar'),'backup-detail','Eye','ghost small',`data-value="${d}"`)}</td></tr>`))}</div><div class="form-actions">${btn(t('Create backup','Yedek oluştur'),'create-backup','DatabaseBackup','primary')}</div>`;
 if(tab==='https')body=`<h2>${t('Alice HTTPS certificate','Alice HTTPS sertifikası')}</h2><p>${t('The certificate presented by this Alice installation.','Bu Alice kurulumunun sunduğu sertifika.')}</p><div class="facts">${fact(t('Subject','Konu'),'alice.atlas.example')}${fact(t('Issuer','Düzenleyen'),'Atlas Enterprise CA')}${fact(t('Expires','Bitiş'),'20 Aug 2027')}${fact(t('State','Durum'),badge(t('Valid','Geçerli'),'success'))}${fact('SHA-256','<code>91:EE:12:44:A3:CE:17:BA:27:4D:61:C1:…</code>')}</div><div class="mt24">${notice(t('Certificate replacement takes effect on the next connection','Sertifika değişimi sonraki bağlantıda uygulanır'),t('Review names and chain completeness before uploading.','Yüklemeden önce adları ve zincirin tam olduğunu kontrol edin.'))}</div><div class="form-actions">${btn(t('Replace certificate','Sertifikayı değiştir'),'replace-https','Upload','primary')}</div>`;
 if(tab==='forwarding')body=`<h2>${t('Audit forwarding','Denetim yönlendirme')}</h2><p>${t('Send audit events to an independent syslog or SIEM destination.','Denetim olaylarını bağımsız bir syslog veya SIEM hedefine yönlendirin.')}</p><form data-form="settings"><div class="grid2">${field(t('Destination host','Hedef sunucu'),'forward-host','siem.atlas.example')}${field(t('Port','Port'),'forward-port',6514,'number')}</div>${selectField(t('Transport','İletim'),'forward-transport',[['tls','TLS'],['tcp','TCP'],['udp','UDP']],'tls')}<div class="facts mt24">${fact(t('Last sent','Son gönderim'),'12 Oct 2026 · 09:41 UTC')}${fact(t('Pending events','Bekleyen olaylar'),'0')}${fact(t('Last delivered sequence','Son iletilen sıra'),'#18429')}</div><div class="form-actions">${btn(t('Save changes','Değişiklikleri kaydet'),'','Check','primary','type="submit"')}</div></form>`;
 if(!body)body=appearance();
 return title(t('Settings','Ayarlar'),t('Make Alice work the way your team does.','Alice’i ekibinizin çalışma biçimine uyarlayın.'))+`<div class="settings-layout"><nav class="settings-nav" aria-label="${t('Settings sections','Ayar bölümleri')}">${tabs.map(([key,ico,label])=>`<button data-go="settings/${key}" class="${key===tab?'active':''}">${icon(ico)}${label}</button>`).join('')}</nav><section class="panel"><div class="panel-body form-section">${body}</div></section></div>${footer()}`;
}
export function usersPage(){if(!isAdmin())return deniedPage();return title(t('People & access','Kişiler ve erişim'),t('Clear responsibilities. Deliberate permissions.','Net sorumluluklar. Bilinçli yetkilendirme.'),btn(t('Add user','Kullanıcı ekle'),'add-user','Plus','primary'))+
`<div class="grid3 mb16">${[['admin',t('Manage the installation, identities and policies.','Kurulumu, kimlikleri ve ilkeleri yönetir.')],['operator',t('Discover inventory and operate certificates and SSH keys.','Envanteri keşfeder, sertifika ve SSH anahtarlarını işletir.')],['auditor',t('Read inventory, inspect evidence and export records.','Envanteri okur, kanıtları inceler ve kayıtları dışa aktarır.')]].map(([role,desc])=>`<div class="micro-card"><div class="flex between"><h3>${statusText(role)}</h3>${icon(role==='admin'?'ShieldCheck':role==='operator'?'Settings2':'Eye')}</div><p>${desc}</p></div>`).join('')}</div><section class="panel mt24">${table([t('Person','Kişi'),t('Role','Rol'),t('Sign-in method','Giriş yöntemi'),t('Status','Durum'),t('Last sign-in','Son giriş'),''],users.map((u,i)=>`<tr><td><div class="flex"><span class="avatar">${u.initials}</span><div><strong>${u.name}</strong><p>${u.email}</p></div></div></td><td><span class="user-role">${statusText(u.role)}</span></td><td>${badge(u.auth,'',u.auth==='TOTP'?'ShieldCheck':'Building2')}</td><td>${badge(t('Active','Etkin'),'success')}</td><td>${u.last}</td><td>${btn(t('Manage','Yönet'),'manage-user','Settings2','ghost small',`data-id="${i}"`)}</td></tr>`))}</section>${footer()}`}
export function licensePage(){if(!canSeeAudit())return deniedPage();const locked=state.license==='locked';return title(t('License','Lisans'),t('A predictable annual license. Your data stays yours.','Öngörülebilir yıllık lisans. Verileriniz size ait.'),isAdmin()?btn(t('Upload license','Lisans yükle'),'upload-license','Upload','primary'):'')+
(locked?notice(t('License expired · external changes paused','Lisans sona erdi · dış değişiklikler duraklatıldı'),t('Inventory, export, audit and backups remain available. Renew to resume changes.','Envanter, dışa aktarma, denetim ve yedekler erişilebilir. Değişiklikler için lisansı yenileyin.'),'danger'):'')+
`<div class="grid2 mt24"><section class="panel license-card"><div class="flex between"><span class="eyebrow">${t('ALICE ANNUAL LICENSE','ALICE YILLIK LİSANS')}</span>${badge(locked?t('Locked','Kilitli'):t('Active','Etkin'),locked?'danger':'success')}</div><h2>Atlas Infrastructure</h2><p class="license-number">ALC-2026-ATLAS-0025</p><div class="license-usage"><div class="flex between"><h3>${t('Managed targets','Yönetilen hedefler')}</h3><span><strong>21</strong><span class="muted"> / 25</span></span></div><div class="progress-track mt16"><span style="width:84%"></span></div><p class="small mt16">${t('4 target slots available · certificates and keys are not counted.','4 hedef kapasitesi kaldı · sertifika ve anahtarlar sayılmaz.')}</p></div><div class="facts">${fact(t('License end','Lisans bitişi'),locked?'30 Sep 2026':'30 Sep 2027')}${fact(t('Installation ID','Kurulum kimliği'),'<code>ALICE-8M4N-2F7B-9R3K-6T1P</code>')}${fact(t('Activation','Etkinleştirme'),t('Signed offline license file','İmzalı çevrimdışı lisans dosyası'))}</div></section><div class="stack">${panel(t('What happens at renewal?','Yenileme sırasında ne olur?'),'',panelBody(`<div class="rule-list">${[[t('Upload the signed file','İmzalı dosyayı yükleyin'),t('Review the customer, validity period and target limit before activation.','Etkinleştirmeden önce kurum adını, süreyi ve hedef sınırını inceleyin.')],[t('Seven-day grace period','Yedi günlük ek süre'),t('Annual licenses keep full operation during the grace period. Evaluation licenses have no grace period.','Yıllık lisanslar ek sürede tam çalışır. Deneme lisansında ek süre yoktur.')],[t('Your inventory remains accessible','Envanteriniz erişilebilir kalır'),t('Lock mode does not delete keys or revoke certificates. In-flight changes finish or roll back safely.','Kilit modu anahtarları silmez veya sertifikaları iptal etmez. Devam eden işlemler tamamlanır ya da güvenle geri alınır.')]].map(([h,p],i)=>`<div class="rule-item"><span class="rule-num">0${i+1}</span><div><h3>${h}</h3><p>${p}</p></div></div>`).join('')}</div>`))}${panel(t('License history','Lisans geçmişi'),'',panelBody(`<div class="activity-item">${icon('CircleCheck','green')}<div><strong>${t('Annual license activated','Yıllık lisans etkinleştirildi')}</strong><p>01 Oct 2026 · Eren Altan</p></div></div><div class="activity-item">${icon('Clock3')}<div><strong>${t('Evaluation started','Deneme başladı')}</strong><p>15 Sep 2026 · 5 ${t('targets','hedef')}</p></div></div>`))}</div></div>${footer()}`}
export function tokensPage(){return title(t('API tokens','API belirteçleri'),t('Personal access for automation, bounded by your role.','Rolünüzle sınırlı, otomasyon için kişisel erişim.'),btn(t('Create token','Belirteç oluştur'),'create-token','Plus','primary'))+
notice(t('Token access never exceeds its owner’s permissions','Belirteç yetkileri sahibinin yetkilerini aşamaz'),t('An auditor can issue read-only tokens. Sensitive browser-only operations cannot be performed with tokens.','Denetçi sadece okuma belirteci oluşturabilir. Hassas, tarayıcıya özel işlemler belirteçlerle yapılamaz.'))+`<section class="panel mt24">${table([t('Name','Ad'),t('Prefix','Ön ek'),t('Access','Erişim'),t('Expires','Bitiş'),t('Last used','Son kullanım'),''],[['Inventory reporting','alc_A7k2…','read','30 Jan 2027','09:30'],['Deployment pipeline','alc_B8n3…',state.role==='auditor'?'read':'operate','31 Dec 2026','08:51']].map(([name,prefix,access,expires,used])=>`<tr><td><strong>${name}</strong></td><td class="mono">${prefix}</td><td>${badge(access==='read'?t('Read only','Salt okunur'):t('Operate','İşlem yetkisi'))}</td><td>${expires}</td><td>${used} UTC</td><td>${btn(t('Revoke','İptal et'),'revoke-token','X','ghost small',`data-value="${name}"`)}</td></tr>`))}</section>${footer()}`}
export function accountPage(){return title(t('Your account','Hesabınız'),t('Personal security, language and workspace preferences.','Kişisel güvenlik, dil ve çalışma alanı tercihleri.'))+`<div class="grid2"><section class="panel"><div class="panel-body"><div class="flex mb16"><span class="avatar" style="width:46px;height:46px;font-size:16px">EA</span><div><h2>Eren Altan</h2><p class="small">${statusText(state.role)} · eren@atlas.example</p></div></div><div class="facts">${fact(t('Sign-in','Oturum açma'),t('Local account + TOTP','Yerel hesap + TOTP'))}${fact(t('Multi-factor authentication','Çok faktörlü doğrulama'),badge(t('Enabled','Etkin'),'success','ShieldCheck'))}</div><div class="form-actions">${btn(t('Recovery codes','Kurtarma kodları'),'recovery-codes','KeyRound')}${btn(t('Change password','Parolayı değiştir'),'change-password','LockKeyhole')}</div></div></section><section class="panel"><div class="panel-body form-section">${appearance()}</div></section></div>${footer()}`}
export function loginPage(){return `<div class="auth-layout"><section class="auth-brand-side"><a class="brand" href="#/overview"><img src="assets/alice.svg" alt="">alice<span class="brand-dot">.</span></a><div class="auth-copy"><div class="eyebrow" style="color:#bfd1c4;margin-bottom:25px">CERTIFICATES. KEYS. CLARITY.</div><h1>${t('A little less uncertainty.<br>A lot more control.','Daha az belirsizlik.<br>Daha fazla kontrol.')}</h1><p>${t('One considered workspace for the certificates and keys your infrastructure depends on.','Altyapınızın dayandığı sertifikalar ve anahtarlar için özenle tasarlanmış tek çalışma alanı.')}</p></div><div class="auth-orbit"></div><div class="auth-brand-footer"><span>${t('Self-hosted','Kendi sunucunuzda')}</span><span>·</span><span>${t('Offline-ready','Çevrimdışı çalışır')}</span><span>·</span><span>${t('Built for control','Kontrol için tasarlandı')}</span></div></section><section class="auth-form-side"><div class="auth-top"><button class="icon-btn" data-action="toggle-theme" aria-label="${t('Toggle theme','Temayı değiştir')}">${icon('Sun')}</button><button class="btn ghost small" data-action="toggle-language">${state.lang==='en'?'TR':'EN'}</button></div><div class="auth-form"><span class="resource-icon">${icon('Fingerprint')}</span><h2>${t('Welcome to Alice','Alice’e hoş geldiniz')}</h2><p>${t('Sign in to your Atlas workspace.','Atlas çalışma alanınıza giriş yapın.')}</p><form data-form="login">${field(t('Username','Kullanıcı adı'),'username','eren','text','', 'autocomplete="username" required')}${field(t('Password','Parola'),'password','','password',t('Design preview: use any sample password.','Tasarım önizlemesi: örnek bir parola kullanın.'),'autocomplete="off" required')}${btn(t('Continue','Devam et'),'','ArrowRight','primary','type="submit"')}</form><div class="auth-divider">${t('or continue with','veya şununla devam edin')}</div>${btn('Microsoft Entra ID','demo-sso','Building2')}<div class="auth-note">${icon('LockKeyhole')}${t('Protected with multi-factor authentication','Çok faktörlü doğrulama ile korunur')}</div>${link(t('Explore the design preview','Tasarım önizlemesini keşfet'),'overview','ArrowUpRight','text-link')}</div><div class="auth-bottom">${t('Interactive design preview · No authentication service connected','Etkileşimli tasarım önizlemesi · Kimlik doğrulama servisi bağlı değil')}</div></section></div>`}
export function setupPage(){const step=state.setupStep;const steps=[t('Welcome & setup code','Karşılama ve kurulum kodu'),t('Administrator & MFA','Yönetici ve MFA'),t('Recovery passphrase','Kurtarma parolası'),t('HTTPS certificate','HTTPS sertifikası'),t('Notifications','Bildirimler'),t('License','Lisans'),t('First target','İlk hedef')];const bodies=[
 `<h1>${t('Make Alice yours.','Alice’i kurmaya başlayın.')}</h1><p>${t('A guided setup for your own infrastructure. Start with the one-time code printed by the installer.','Kendi altyapınız için rehberli kurulum. Yükleyicinin verdiği tek kullanımlık kodla başlayın.')}</p>${field(t('Setup code','Kurulum kodu'),'setup-code','ALICE-DEMO-2026','text',t('This is a visual walkthrough. No installation is modified.','Bu bir görsel akış örneğidir. Hiçbir kurulum değiştirilmez.'))}${selectField(t('Language','Dil'),'setup-language',[['en','English'],['tr','Türkçe']],state.lang)}`,
 `<h1>${t('Create your administrator','Yöneticinizi oluşturun')}</h1><p>${t('Local administrator accounts require TOTP. Enrollment is completed before this account can be used.','Yerel yönetici hesapları TOTP gerektirir. Hesap kullanılmadan önce kayıt tamamlanır.')}</p>${field(t('Display name','Görünen ad'),'setup-name','Eren Altan')}${field(t('Email','E-posta'),'setup-email','eren@atlas.example','email')}${notice(t('Mandatory verification step','Zorunlu doğrulama adımı'),t('The production flow presents an authenticator QR code, verifies a TOTP code, then shows recovery codes once.','Üretim akışı doğrulayıcı QR kodunu sunar, TOTP kodunu doğrular ve kurtarma kodlarını bir kez gösterir.'))}`,
 `<h1>${t('Prepare for recovery','Kurtarmaya hazırlanın')}</h1><p>${t('A recovery passphrase is required to restore encrypted backups. Keep it outside the Alice server.','Şifreli yedekleri geri yüklemek için kurtarma parolası gerekir. Parolayı Alice sunucusu dışında saklayın.')}</p>${notice(t('A passphrase you can recover','Geri erişebileceğiniz bir parola'),t('The production form includes strength feedback and confirmation. This design preview does not collect secrets.','Üretim formunda güç geri bildirimi ve tekrar onayı bulunur. Bu tasarım önizlemesi gizli bilgi toplamaz.'))}<div class="check-option mt24"><input type="checkbox" checked id="recovery-demo"><label for="recovery-demo">${t('I have stored the recovery information securely.','Kurtarma bilgilerini güvenle sakladım.')}</label></div>`,
 `<h1>${t('Secure the connection','Bağlantıyı güvenceye alın')}</h1><p>${t('Choose the HTTPS certificate used by the Alice web interface.','Alice web arayüzünün kullanacağı HTTPS sertifikasını seçin.')}</p><div class="check-option"><input type="radio" name="https-choice" checked id="https-upload"><label for="https-upload">${t('Upload a certificate and key','Sertifika ve anahtar yükle')}<p>PEM / PFX</p></label></div><div class="check-option"><input type="radio" name="https-choice" id="https-temp"><label for="https-temp">${t('Keep temporary certificate for now','Şimdilik geçici sertifikayı koru')}<p>${t('Replace it before production use.','Üretim kullanımından önce değiştirin.')}</p></label></div>`,
 `<h1>${t('Keep the right people informed','Doğru kişileri bilgilendirin')}</h1><p>${t('Connect SMTP for expiry and operational alerts. You can configure this later.','Bitiş ve operasyon uyarıları için SMTP bağlayın. Daha sonra yapılandırabilirsiniz.')}</p>${field(t('SMTP server','SMTP sunucusu'),'setup-smtp','smtp.atlas.example')}${field(t('Recipient','Alıcı'),'setup-recipient','operations@atlas.example','email')}${badge(t('Optional step','İsteğe bağlı adım'))}`,
 `<h1>${t('Choose your license','Lisansınızı seçin')}</h1><p>${t('Activate offline or start a 30-day evaluation.','Çevrimdışı etkinleştirin veya 30 günlük deneme başlatın.')}</p><div class="check-option"><input type="radio" checked name="license-choice" id="license-eval"><label for="license-eval"><b>${t('Start evaluation','Denemeyi başlat')}</b><p>30 ${t('days','gün')} · 5 ${t('targets','hedef')}</p></label></div><div class="check-option"><input type="radio" name="license-choice" id="license-file"><label for="license-file"><b>${t('Upload signed license','İmzalı lisans yükle')}</b><p>${t('Works without an internet connection','İnternet bağlantısı olmadan çalışır')}</p></label></div>`,
 `<h1>${t('Connect your first target','İlk hedefinizi bağlayın')}</h1><p>${t('Prepare the remote service account, then confirm the observed host fingerprint.','Uzak servis hesabını hazırlayın, ardından gözlemlenen sunucu parmak izini doğrulayın.')}</p>${field(t('Server name','Sunucu adı'),'setup-target','nginx-prod-01')}${field(t('Address','Adres'),'setup-address','10.24.1.20')}${notice(t('Verify identity before discovery','Keşiften önce kimliği doğrulayın'),t('First contact requires administrator confirmation of the SSH host key.','İlk bağlantı, SSH sunucu anahtarının yönetici tarafından onaylanmasını gerektirir.'))}`
 ];return `<div class="setup-layout"><div class="flex between"><a class="brand" href="#/overview" style="padding:0"><img src="assets/alice.svg" alt="">alice.</a><div class="flex">${badge(t('Setup walkthrough','Kurulum akışı'))}${btn(t('Exit preview','Önizlemeden çık'),'go-overview','X','ghost small')}</div></div><div class="setup-shell"><aside class="setup-steps"><h3>${t('Your private workspace','Size ait çalışma alanı')}</h3>${steps.map((name,i)=>`<div class="setup-step ${i===step?'active':''}"><span class="setup-step-number">${i<step?icon('Check'):i+1}</span>${name}</div>`).join('')}</aside><section class="setup-content">${bodies[step]}<div class="form-actions">${step?btn(t('Back','Geri'),'setup-back','ArrowLeft'):''}${btn(step===6?t('Open workspace','Çalışma alanını aç'):t('Continue','Devam et'),'setup-next','ArrowRight','primary')}</div><p class="small muted mt24">${t('Visual walkthrough only. All security checks remain required in the production flow.','Sadece görsel akış örneği. Üretim akışında tüm güvenlik kontrolleri zorunlu kalır.')}</p></section></div></div>`}
